observers.expression:
useQueries({
    queries: visibleRecentEntries.map((entry) => ({
      ...(entry.type === "issue"
        ? issueDetailOptions(wsId, entry.id)
        : projectDetailOptions(wsId, entry.id)),
      enabled: recentsEnabled,
      staleTime: 30_000,
    })),
  })

useQuery({
    ...pinListOptions(wsId, userId ?? "", { enabled: afterFirstScreen }),
    enabled: !!userId && afterFirstScreen,
  })

useQuery({
    ...issueDetailOptions(wsId, id),
    initialData: () => {
      const cached = findCachedIssue(queryClient, wsId, id);
      return cached?.description != null
        && cached.pending_decision_count !== undefined
        && Object.prototype.hasOwnProperty.call(cached, "parent_done_grant")
        ? cached
        : undefined;
    },
  })

useQuery({
    ...issueDetailOptions(wsId, parentIssueId ?? ""),
    enabled: !!parentIssueId,
    initialData: () =>
      parentIssueId ? findCachedIssue(queryClient, wsId, parentIssueId) : undefined,
  })

useQuery({
    ...pinListOptions(wsId ?? "", userId ?? "", { enabled: shellGateOpen }),
    enabled: !!wsId && !!userId && shellGateOpen,
  })

useQuery({
    ...pinListOptions(wsId, userId ?? "", { enabled: afterFirstScreen }),
    enabled: !!userId && afterFirstScreen,
  })

useQueries({
    queries: recentItems.map((item) => ({
      ...issueDetailOptions(wsId, item.id),
      enabled: open,
    })),
  })

unscopedInvalidations.expression:
qc.invalidateQueries({
    predicate: (query) => {
      const key = query.queryKey;
      return (
        key[0] === "workspaces" &&
        key[1] === wsId &&
        key[2] === "squads" &&
        key[4] === "members-status"
      );
    },
  })

allQueryOperations.expression:
useQuery({
    queryKey: ["agent-detail-probe", wsId, agentId],
    queryFn: () => api.getAgent(agentId),
    enabled: !agentsLoading && !agent && !!agentId,
    retry: false,
  })

useQuery(
    autopilotDeliveryOptions(wsId, autopilotId, delivery.id, { enabled: open }),
  )

useQueries({
    queries: visibleRecentEntries.map((entry) => ({
      ...(entry.type === "issue"
        ? issueDetailOptions(wsId, entry.id)
        : projectDetailOptions(wsId, entry.id)),
      enabled: recentsEnabled,
      staleTime: 30_000,
    })),
  })

useQuery({
    queryKey: ["attachment-content", attachmentId ?? ""] as const,
    queryFn: () => api.getAttachmentTextContent(attachmentId as string),
    enabled: !!attachmentId,
    // 413 / 415 won't become 200 on retry; a transport error is easier to
    // recover from by re-opening than waiting on background retries with
    // no UI affordance.
    retry: false,
    staleTime: 5 * 60_000,
    gcTime: 30 * 60_000,
  })

useQuery(autopilotRunOptions(wsId, autopilotId, runId, {
    enabled: open && Boolean(autopilotId && runId),
  }))

useQuery({
    queryKey: issueKeys.tasks(issue.id),
    queryFn: () => api.listTasksByIssue(issue.id),
    staleTime: 30_000,
