useQuery({
    ...pinListOptions(wsId, userId ?? "", { enabled: afterFirstScreen }),
    enabled: !!userId && afterFirstScreen,
  })

useQuery({
    queryKey: issueKeys.tasks(issueId),
    queryFn: () => api.listTasksByIssue(issueId),
    enabled: Boolean(taskId),
    staleTime: 30_000,
  })

useQuery({
    queryKey: issueKeys.tasks(issueId),
    queryFn: () => api.listTasksByIssue(issueId),
