    enabled: isIntake,
    refetchInterval: isIntake && !isTerminal ? 5_000 : false,
  })

useQuery({
    ...issueDetailOptions(wsId, id),
    initialData: () => {
      const cached = findCachedIssue(queryClient, wsId, id);
      return cached?.description != null
        && cached.pending_decision_count !== undefined
