useQuery({
    ...projectDocDetailOptions(
      workspaceId,
      selectedSource?.kind === "project" ? selectedSource.id : "",
      selectedSource?.kind === "project" ? selectedMetadata?.slug || selectedMetadata?.id || "" : "",
